  @protected
  void sse_encode_playback(Playback self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case Playback_Idle():
        sse_encode_i_32(0, serializer);
      case Playback_Ended(trackId: final trackId):
        sse_encode_i_32(1, serializer);
        sse_encode_String(trackId, serializer);
      case Playback_Buffering(
        trackId: final trackId,
        positionMs: final positionMs,
        durationMs: final durationMs,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(trackId, serializer);
        sse_encode_u_64(positionMs, serializer);
        sse_encode_u_64(durationMs, serializer);
      case Playback_Playing(
        trackId: final trackId,
        positionMs: final positionMs,
        durationMs: final durationMs,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_String(trackId, serializer);
        sse_encode_u_64(positionMs, serializer);
        sse_encode_u_64(durationMs, serializer);
      case Playback_Paused(
        trackId: final trackId,
        positionMs: final positionMs,
        durationMs: final durationMs,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_String(trackId, serializer);
        sse_encode_u_64(positionMs, serializer);
        sse_encode_u_64(durationMs, serializer);
      case Playback_Failed(trackId: final trackId, code: final code):
        sse_encode_i_32(5, serializer);
        sse_encode_opt_String(trackId, serializer);
        sse_encode_String(code, serializer);
    }
  }

